//! The AutoCAD Color Index.
//!
//! DXF entities mostly carry a palette index rather than an RGB value, plus the two indirections
//! `ByLayer` (256) and `ByBlock` (0). Resolving those is `convert`'s job; this module only owns the
//! palette itself and the background-dependent rule for index 7.
//!
//! The table is the standard 256-entry AutoCAD palette, transcribed from ezdxf's
//! `DXF_DEFAULT_COLORS` (MIT licensed). It is *not* generated by an HSV formula — the entries
//! deviate from one in 111 of 240 places, so it is stored literally.

use crate::scene::Rgb;

/// `ByBlock`: inherit the colour of the enclosing INSERT.
pub const BY_BLOCK: i16 = 0;
/// `ByLayer`: inherit the colour of the entity's layer.
pub const BY_LAYER: i16 = 256;

/// The AutoCAD Color Index palette, indices 0..=255.
