/// Resolve an ACI index to an RGB value.
///
/// Index 7 is the drawing's "foreground" colour: it is white on a dark background and black on a
/// light one, which is why the background has to be passed in. Out-of-range indices fall back to
/// the foreground rather than vanishing.
pub fn rgb(index: i16, dark_background: bool) -> Rgb {
    let fg = if dark_background { Rgb::WHITE } else { Rgb::BLACK };
    match index {
        7 => fg,
        1..=255 => PALETTE[index as usize],
        // Negative indices mark a layer that is switched off; the colour is still |index|.
        -255..=-1 => rgb(-index, dark_background),
        _ => fg,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn primaries_match_the_autocad_palette() {
        assert_eq!(PALETTE[1], Rgb(0xFF, 0x00, 0x00), "1 red");
        assert_eq!(PALETTE[2], Rgb(0xFF, 0xFF, 0x00), "2 yellow");
        assert_eq!(PALETTE[3], Rgb(0x00, 0xFF, 0x00), "3 green");
        assert_eq!(PALETTE[4], Rgb(0x00, 0xFF, 0xFF), "4 cyan");
        assert_eq!(PALETTE[5], Rgb(0x00, 0x00, 0xFF), "5 blue");
        assert_eq!(PALETTE[6], Rgb(0xFF, 0x00, 0xFF), "6 magenta");
        assert_eq!(PALETTE[7], Rgb(0xFF, 0xFF, 0xFF), "7 white");
        assert_eq!(PALETTE[8], Rgb(0x80, 0x80, 0x80), "8 dark grey");
        assert_eq!(PALETTE[9], Rgb(0xC0, 0xC0, 0xC0), "9 light grey");
        assert_eq!(PALETTE[255], Rgb(0xFF, 0xFF, 0xFF), "255 white");
        assert_eq!(PALETTE[250], Rgb(0x00, 0x00, 0x00), "250 black");
    }

    #[test]
    fn the_palette_has_the_expected_shape() {
        // Indices 10..250 are 24 hue blocks of 10; each block starts at full brightness.
        for h in 0..24 {
            let base = 10 + h * 10;
            let full = PALETTE[base];
            let max = full.0.max(full.1).max(full.2);
            assert_eq!(max, 0xFF, "hue block {h} should start fully saturated, got {full:?}");
        }
        // 250..=255 is a grey ramp.
        for w in 250..255 {
            assert!(PALETTE[w].luma() <= PALETTE[w + 1].luma(), "grey ramp reverses at {w}");
        }
    }

    #[test]
    fn index_seven_follows_the_background() {
        assert_eq!(rgb(7, true), Rgb::WHITE);
        assert_eq!(rgb(7, false), Rgb::BLACK);
        // Everything else is background-independent.
        for i in [1, 2, 5, 30, 140, 255] {
            assert_eq!(rgb(i, true), rgb(i, false));
            assert_eq!(rgb(i, true), PALETTE[i as usize]);
        }
    }

    #[test]
    fn out_of_range_indices_fall_back_to_the_foreground() {
        for i in [BY_BLOCK, BY_LAYER, 300, i16::MAX, i16::MIN] {
            assert_eq!(rgb(i, true), Rgb::WHITE);
            assert_eq!(rgb(i, false), Rgb::BLACK);
        }
    }

    #[test]
    fn a_negated_index_still_yields_its_colour() {
        // DXF switches a layer off by negating its colour index; the colour itself survives.
        assert_eq!(rgb(-5, true), PALETTE[5]);
        assert_eq!(rgb(-255, true), PALETTE[255]);
    }
}
